class Solution:
    def numIslands(self, grid: List[List[str]]) -> int:
        m, n = len(grid), len(grid[0])
        count = 0

        def dfs(i, j):
            # 先把当前格子淹掉，防止重复访问
            grid[i][j] = '0'
            # 上下左右四个方向扩散
            for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ni, nj = i + di, j + dj
                # 邻居在边界内且是陆地，继续淹
                if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == '1':
                    dfs(ni, nj)

        # 遍历每个格子，发现新的 '1' 就是一座新岛
        for i in range(m):
            for j in range(n):
                if grid[i][j] == '1':
                    count += 1  # 发现新岛
                    dfs(i, j)   # 把整座岛淹掉
        return count

