            # 终止条件：凑齐了，收集当前路径
            if target == 0:
                result.append(path.copy())
                return 
            for i in range(start, len(candidates)):
                # 剪枝：当前数已经比剩余 target 大，后面的更大，直接跳出
                if candidates[i] > target:
                    break
                path.append(candidates[i])          # 做选择
                method(i, target - candidates[i])   # 递归（传 i，允许重复选）
                path.pop()                          # 撤销选择（回溯）

        method(0, target)

        return result

