class Solution:
    def sortColors(self, nums: List[int]) -> None:
        p0 = 0          # 0 区的右边界，nums[0..p0-1] == 0
        p2 = len(nums) - 1  # 2 区的左边界，nums[p2+1..] == 2
        p = 0           # 当前遍历指针

        while p <= p2:
            if nums[p] == 0:
                # 把 0 换到左边，p0 和 p 都前进
                nums[p], nums[p0] = nums[p0], nums[p]
                p0 += 1
            elif nums[p] == 2:
                # 把 2 换到右边，p2 左移，p 不动（换来的元素没检查过）
                nums[p], nums[p2] = nums[p2], nums[p]
                p2 -= 1
            else:
                # nums[p] == 1，留在中间
                p += 1

            # p 落后 p0 时补上（0 换走后 p0 推进，但 p 没加，需要对齐）
            if p < p0:
                p = p0

